blobs.dc3193c1335c:
// "glow" — a SHADER: picture in, picture out, and an optional audio input that drives it.
//
// The folder it sits in (`_modules/shaders/`) is what says so; nothing here names a plugin,
// because there is none. What this module DOES is the GLSL under `shaders/`, one folder per
// shader, and `shader:` below picks which of them runs.
//
// `P1`..`P4` are the four knobs every shader gets, 0..1, reaching the fragment as `uP1`..`uP4`.
// What each one means is the shader's business — read the comments in its fragment.glsl.
// See packages/song-video/docs/shaders.md.
type("shader")
shader("pulse")
params({
  P1: 0.6, // pulse: how hard the sound lifts the picture
  P2: 0.35, // pulse: vignette
  P3: 0,
  P4: 0,
})

blobs.dd3f7fb25983:
// The Tracktion built-in 4OSC synth. It sits in instruments/, so it's a
// midi -> audio plugin with a mandatory MIDI input — both derived from the folder.
// `plugin.type` is the FORMAT: "internal" for a built-in, whose xmlTypeName goes in
// `name` (an external plugin uses type: "vst3" / "au" / … and name: its real name).
plugin({ type: "internal", name: "4osc" })
// The UI every module that extends this one draws inside its rectangle on the Chains
// graph. The extending module overrides one widget by restating it under the same id.
//
// The ranges are 4OSC's own. A built-in's params are in NATIVE units, not the 0..1
// an external plugin reports: "Filter Freq" is a 0..135 note-ish scale rather than
// Hz, and "Level" is dB. They have to be written down here — nothing reports a
// parameter's bounds at runtime, so an unranged control would be guessing.
ui({
  cols: 4,
  rows: 2,
  widgets: {
    title: { type: "label", col: 0, row: 0, colSpan: 2, text: "4OSC" },
    cutoff: {
      type: "knob",
      col: 0,
      row: 1,
      label: "Cutoff",
      bind: "Filter Freq",
      min: 0,
      max: 135.076232,
    },
    res: { type: "knob", col: 1, row: 1, label: "Res", bind: "Filter Resonance", min: 0, max: 100 },
    level: { type: "slider", col: 2, row: 1, label: "Level", bind: "Level", min: -100, max: 0 },
  },
})

blobs.e01045aff1ce:
// turntable — the PLATTER: a record, its speed, and a needle you put down. A deck's SOURCE: it
// takes no input and makes its sound from the file the desk hands it, the one module whose material
// arrives at RUN time rather than from the project. Shipped with k7, since a set cannot play
// without it (packages/song/docs/metaModules.md).
//
// No jsdsp: the engine hosts the platter (`studio_turntable`), which decodes the record WHOLE so a
// scratch can read it backwards (engine/k7-runtime/docs/turntable.md).
//
// THE RECORD IS NOT A PARAM. A param is a number; the record is a path, and it changes when another
// one goes on. It travels in the document's `deckFile`, which the desk fills (docs/platter-node-plan.md).
plugin({ type: "internal", name: "studio_turntable" })
params({
  // STOPPED: a platter put down must not start turning on its own, and 0 is a real stop.
  Rate: 0,
  // Where the needle lands, 0..1 of the record — a JUMP, applied only when the value CHANGES.
  Seek: 0,
  Gain: 1,
  // Hold the PITCH while the speed moves. Off: a platter is a varispeed, and that is its sound.
  Key: 0,
})

