args:
// An AUDIO clip living in the same clips/ folder — proves the two kinds coexist and
// are told apart by extension.

source("clips/kick.wav")

vectors.ret:
// A live Strudel (TidalCycles-in-JS) pattern, linked by the "pad" and "kit" tracks.
// The engine plays it on them while the transport rolls, locked to the beat — edit +
// save to hear it change live.
//
// `.label(...)` names the lane a part plays on. A label matching a strudel track's
// name lands there — "Pad" on the "pad" track, so it plays through that track's chain
// and mixer strip. A label no track declares still plays, on the file's first track by
// name ("kit"); so does an unlabelled part.
//
// What `s(...)` means is the event's business: a name found as a sample — in your
// project's `samples/` folder, $DIRT_SAMPLES or $STRUDEL_SAMPLES — is a one-shot,
// anything else is a note for the lane's instrument ("sawtooth" on "pad").
stack(
  note("c e g c5").s("sawtooth").slow(2).label("Pad"),
  sound("bd hh sn hh").label("Kit"),
)

args:
// A hand-drawn filter sweep, read 0..1: up across bar 1, held through bar 2, then
// back down by the top of bar 4.

type("custom")
points([
  time("1:1:1").value(0),
  time("2:1:1").value(1),
  time("3:1:1").value(0.5),
  time("4:1:1").value(0.2),
])

// A hand-drawn filter sweep, read 0..1: up across bar 1, held through bar 2, then
// back down by the top of bar 4.

type("custom")
points([
  time("1:1:1").value(0),
  time("2:1:1").value(1),
  time("3:1:1").value(1),
  time("4:1:1").value(0.2),
])

// A hand-drawn filter sweep, read 0..1: up across bar 1, held through bar 2, then
// back down by the top of bar 4.

type("custom")
points([
  time("1:1:1").value(0),
  time("2:1:1").value(1),
  time("4:1:1").value(0.25),
])

// The panel drawn inside this node's card on the graph.
//
// The dropdown binds `@shader` and says NOTHING about its entries: which shaders exist is a fact
// about the folder, and a list written here would be a copy of a directory going stale between
// saves. The graph fills it from what the loader found — the same arrangement `@base` has.
cols(4)
rows(2)
widgets({
  pick: { type: "dropdown", col: 0, row: 0, colSpan: 4, bind: "@shader" },
  p1: { type: "knob", col: 0, row: 1, bind: "P1", min: 0, max: 1, step: 0.01 },
  p2: { type: "knob", col: 1, row: 1, bind: "P2", min: 0, max: 1, step: 0.01 },
  p3: { type: "knob", col: 2, row: 1, bind: "P3", min: 0, max: 1, step: 0.01 },
  p4: { type: "knob", col: 3, row: 1, bind: "P4", min: 0, max: 1, step: 0.01 },
})

// The panel drawn inside this node's card on the graph: the shader picker and the four knobs.
cols(4)
rows(2)
widgets({
  pick: { type: "dropdown", col: 0, row: 0, colSpan: 4, bind: "@shader" },
  p1: { type: "knob", col: 0, row: 1, bind: "P1", min: 0, max: 1, step: 0.01 },
  p2: { type: "knob", col: 1, row: 1, bind: "P2", min: 0, max: 1, step: 0.01 },
  p3: { type: "knob", col: 2, row: 1, bind: "P3", min: 0, max: 1, step: 0.01 },
  p4: { type: "knob", col: 3, row: 1, bind: "P4", min: 0, max: 1, step: 0.01 },
})

// mixer — the strip, two columns: Volume's fader over Pan, and beside them the three bands a lane is sat in a mix with
cols(2)
rows(4)
widgets({
  w1: { type: "fader", col: 0, row: 0, rowSpan: 3, label: "Volume", bind: "Volume", min: -60, max: 6 },
  w2: { type: "knob", col: 0, row: 3, label: "Pan", bind: "Pan", min: -1, max: 1 },
  w5: { type: "knob", col: 1, row: 0, label: "High", bind: "High", min: -18, max: 18 },
  w4: { type: "knob", col: 1, row: 1, label: "Mid", bind: "Mid", min: -18, max: 18 },
  w3: { type: "knob", col: 1, row: 2, label: "Low", bind: "Low", min: -18, max: 18 },
  // The lane heard 10 dB up while it is on, its fader untouched (packages/song/docs/highlight.md).
  w6: { type: "button", col: 1, row: 3, label: "+10", bind: "@highlight" },
})

// turntable — the platter's four numbers. Only `Rate` is a continuous gesture, hence the fader.
//
// The ranges are the PLUGIN's own (engine/k7-runtime/engine/TurntablePlugin.cpp): a desk binding
// must not be able to ask for a speed this panel refuses to draw. `Rate` is SIGNED and rests at 0,
// which is the STOP: a platter has no neutral position, it has a stop, and the record's speed is 1.
// The record is not here and cannot be: it is the document's `deckFile`, filled at run time.
cols(3)
rows(3)
widgets({
  rate: { type: "fader", col: 0, row: 0, rowSpan: 3, label: "Vitesse", bind: "Rate", min: -4, max: 4, step: 0.01 },
  seek: { type: "knob", col: 2, row: 0, label: "Aiguille", bind: "Seek", min: 0, max: 1, step: 0.001 },
  gain: { type: "knob", col: 2, row: 1, label: "Niveau", bind: "Gain", min: 0, max: 2, step: 0.01 },
  key: { type: "toggle", col: 2, row: 2, label: "Key", bind: "Key" },
})

// video-mixer — the picture strip, the audio strip's two columns by four rows: the channels, then transparency.
cols(2)
rows(4)
widgets({
  red: { type: "knob", col: 0, row: 0, rowSpan: 2, label: "Red", bind: "P1", min: 0, max: 1, step: 0.01 },
  green: { type: "knob", col: 1, row: 0, rowSpan: 2, label: "Green", bind: "P2", min: 0, max: 1, step: 0.01 },
  blue: { type: "knob", col: 0, row: 2, rowSpan: 2, label: "Blue", bind: "P3", min: 0, max: 1, step: 0.01 },
  transparency: { type: "knob", col: 1, row: 2, rowSpan: 2, label: "Transparency", bind: "P4", min: 0, max: 1, step: 0.01 },
})
